// @pit: {"label": "Gather rate paths, Nasdaq blow-off stats, mega-cap valuations, repo lint config"}
async ({ http: { request }, market: { valuation }, workspace: { read, glob } }) => {
  const H = { "User-Agent": "Mozilla/5.0" };
  const fred = async (id: string) => { const b = (await request(`https://fred.stlouisfed.org/graph/fredgraph.csv?id=${id}`, { maxBytes: 1_000_000, headers: H })).body; return Object.fromEntries(b.trim().split("\n").slice(1).map((l) => [l.slice(0, 7), +l.split(",")[1]])); };
  const y = (s: string) => `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s)}?period1=473385600&period2=1794787200&interval=1mo`;
  const [ff, t10, ndxB, val, pkg, husky] = await Promise.all([fred("FEDFUNDS"), fred("GS10"), request(y("^IXIC"), { maxBytes: 1_000_000, headers: H }),
    valuation({ tickers: ["NVDA", "MSFT", "AAPL", "AMZN", "GOOGL", "META", "AVGO", "TSLA"] }).catch((e) => String(e)), read("package.json", { format: "raw" }), glob([".husky/*"], { dot: true })]);
  const j = JSON.parse(ndxB.body).chart.result[0]; const nd: Record<string, number> = {}; j.timestamp.forEach((t: number, i: number) => { nd[new Date(t * 1000 + 86400000 * 3).toISOString().slice(0, 7)] = j.indicators.quote[0].close[i]; });
  const pick = (o: Record<string, number>, ks: string[]) => Object.fromEntries(ks.map((k) => [k, o[k] ?? null]));
  const rk = ["1998-10", "1999-01", "1999-06", "1999-08", "1999-12", "2000-03", "2000-05", "2000-12", "2001-06", "2001-12", "2022-11", "2023-07", "2024-06", "2024-12", "2025-06", "2025-12", "2026-03", "2026-06", "2026-08", "2026-09", "2026-10"];
  const curMax = Object.entries(nd).filter(([k]) => k >= "2022-11").sort((a, b) => b[1] - a[1])[0];
  return { ff: pick(ff, rk), t10: pick(t10, rk), ndx: pick(nd, ["1999-08", "1999-12", "2000-02", "2000-03", "2002-09", "2026-08", "2026-09", "2026-10", "2026-11"]), curMax,
    val: typeof val === "string" ? val : { data: val.data, url: val.url, sources: val.sources }, scripts: JSON.parse(pkg.content).scripts, lintstaged: JSON.parse(pkg.content)["lint-staged"] ?? null, husky: husky.entries } as PitJsonValue;
}
